"""Safe filter-expression evaluator for event dicts (Python stdlib only).

compile_filter(src) -> callable(event) -> bool

Grammar (recursive descent, no eval/exec anywhere):

    expr        := or_expr
    or_expr     := and_expr ('||' and_expr)*          # lowest precedence
    and_expr    := unary ('&&' unary)*
    unary       := '!' unary | comparison
    comparison  := operand (COMP_OP operand)?         # COMP_OP binds tightest
                 | operand 'in' list_literal
    operand     := NUMBER | STRING | dotted.path

Dotted paths are looked up in nested dicts; a missing key yields the
MISSING sentinel, which fails every comparison (including == and !=)
but is distinguishable by exists(path).
"""

from __future__ import annotations

from typing import Any, Callable, Dict, List, Sequence, Tuple


# ---------------------------------------------------------------------------
# MISSING sentinel
# ---------------------------------------------------------------------------

class _MissingType:
    """Distinct singleton signalling 'path not found'.

    Fails *all* comparisons (even ``missing == missing``) so filters can
    rely on plain comparison operators without special-casing None.
    """

    _instance: "_MissingType | None" = None

    def __new__(cls) -> "_MissingType":
        if cls._instance is None:
            cls._instance = super().__new__(cls)
        return cls._instance

    def __repr__(self) -> str:  # pragma: no cover - debug aid
        return "MISSING"

    def __bool__(self) -> bool:
        raise TypeError("MISSING has no truth value")

    def __eq__(self, other: object) -> bool:
        raise TypeError("MISSING cannot participate in comparisons")


MISSING = _MissingType()


def lookup(event: Any, parts: Sequence[str]) -> Any:
    """Walk *parts* through nested mappings; MISSING on any miss."""
    cur = event
    for part in parts:
        try:
            cur = cur[part]
        except (KeyError, TypeError):
            return MISSING
    return cur


# ---------------------------------------------------------------------------
# Tokenizer
# ---------------------------------------------------------------------------

_TWO_CHAR = {"==", "!=", "<=", ">=", "&&", "||"}
_ONE_CHAR = set("<>!()[]")


class Token:
    __slots__ = ("kind", "value", "pos")

    def __init__(self, kind: str, value: Any, pos: int) -> None:
        self.kind = kind
        self.value = value
        self.pos = pos

    def __repr__(self) -> str:  # pragma: no cover - debug aid
        return f"Token({self.kind!r}, {self.value!r})"


def tokenize(src: str) -> List[Token]:
    tokens: List[Token] = []
    i, n = 0, len(src)
    while i < n:
        c = src[i]
        if c.isspace():
            i += 1
            continue
        two = src[i:i + 2]
        if two in _TWO_CHAR:
            tokens.append(Token("op", two, i))
            i += 2
            continue
        if c in _ONE_CHAR:
            tokens.append(Token("op", c, i))
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and src[j].isdigit():
                j += 1
            if j < n and src[j] == "." and j + 1 < n and src[j + 1].isdigit():
                j += 1
                while j < n and src[j].isdigit():
                    j += 1
                tokens.append(Token("number", float(src[i:j]), i))
            else:
                tokens.append(Token("number", int(src[i:j]), i))
            i = j
            continue
        if c in "\"'":
            quote = c
            j = i + 1
            buf: List[str] = []
            while j < n and src[j] != quote:
                if src[j] == "\\" and j + 1 < n and src[j + 1] in (quote, "\\"):
                    buf.append(src[j + 1])
                    j += 2
                else:
                    buf.append(src[j])
                    j += 1
            if j >= n:
                raise SyntaxError(f"unterminated string at position {i}")
            tokens.append(Token("string", "".join(buf), i))
            i = j + 1
            continue
        if c.isalpha() or c == "_":
            j = i
            while j < n and (src[j].isalnum() or src[j] in "._"):
                j += 1
            word = src[i:j]
            if word in ("in", "exists"):
                tokens.append(Token(word, word, i))
            elif ".." in word or word.endswith("."):
                raise SyntaxError(f"malformed path {word!r} at position {i}")
            else:
                tokens.append(Token("path", tuple(word.split(".")), i))
            i = j
            continue
        raise SyntaxError(f"unexpected character {c!r} at position {i}")
    tokens.append(Token("eof", None, n))
    return tokens


# ---------------------------------------------------------------------------
# Parser -> evaluator closures
# ---------------------------------------------------------------------------

_CMP_OPS = {"==", "!=", "<", "<=", ">", ">="}

ValueFn = Callable[[Any], Any]
PredFn = Callable[[Any], bool]


class _Parser:
    def __init__(self, tokens: List[Token]) -> None:
        self.tokens = tokens
        self.i = 0

    # -- token helpers ------------------------------------------------------
    def peek(self) -> Token:
        return self.tokens[self.i]

    def next(self) -> Token:
        tok = self.tokens[self.i]
        self.i += 1
        return tok

    def expect_op(self, op: str) -> None:
        tok = self.next()
        if tok.kind != "op" or tok.value != op:
            raise SyntaxError(
                f"expected {op!r} at position {tok.pos}, got {tok.value!r}")

    def at_op(self, *ops: str) -> bool:
        tok = self.peek()
        return tok.kind == "op" and tok.value in ops

    # -- grammar ------------------------------------------------------------
    def parse(self) -> PredFn:
        fn = self.or_expr()
        tok = self.peek()
        if tok.kind != "eof":
            raise SyntaxError(
                f"unexpected trailing input at position {tok.pos}: {tok.value!r}")
        return fn

    def or_expr(self) -> PredFn:
        left = self.and_expr()
        while self.at_op("||"):
            self.next()
            right = self.and_expr()
            left = _make_or(left, right)
        return left

    def and_expr(self) -> PredFn:
        left = self.unary()
        while self.at_op("&&"):
            self.next()
            right = self.unary()
            left = _make_and(left, right)
        return left

    def unary(self) -> PredFn:
        if self.at_op("!"):
            self.next()
            inner = self.unary()
            return lambda event: not inner(event)
        return self.comparison()

    def comparison(self) -> PredFn:
        left_fn = self.operand()
        tok = self.peek()
        if tok.kind in _CMP_OPS:
            self.next()
            right_fn = self.operand()
            return _make_cmp(tok.kind, left_fn, right_fn)
        if tok.kind == "in":
            self.next()
            container = self.list_literal()
            return _make_in(left_fn, container)
        # bare operand: truthiness of a present value
        return _make_truthy(left_fn)

    def list_literal(self) -> ValueFn:
        self.expect_op("[")
        items: List[ValueFn] = []
        if not self.at_op("]"):
            items.append(self.operand())
            while self.at_op(","):
                self.next()
                items.append(self.operand())
        self.expect_op("]")
        return lambda event: [fn(event) for fn in items]

    def operand(self) -> ValueFn:
        tok = self.next()
        if tok.kind == "number":
            value = tok.value
            return lambda event: value
        if tok.kind == "string":
            value = tok.value
            return lambda event: value
        if tok.kind == "path":
            parts = tok.value
            return lambda event: lookup(event, parts)
        raise SyntaxError(
            f"expected literal or path at position {tok.pos}, got {tok.value!r}")


# Closure factories kept at module level so they pickle cleanly and stay
# free of any dynamic code execution.

def _make_or(left: PredFn, right: PredFn) -> PredFn:
    def fn(event: Any) -> bool:
        lv = left(event)
        if lv is True:
            return True  # real short-circuit: right side never evaluated
        rv = right(event)
        return bool(lv) or bool(rv)
    return fn


def _make_and(left: PredFn, right: PredFn) -> PredFn:
    def fn(event: Any) -> bool:
        lv = left(event)
        if lv is False:
            return False  # real short-circuit: right side never evaluated
        rv = right(event)
        return bool(lv) and bool(rv)
    return fn


def _make_truthy(fn: ValueFn) -> PredFn:
    def pred(event: Any) -> bool:
        value = fn(event)
        if value is MISSING:
            return False
        return bool(value)
    return pred


def _make_cmp(op: str, lf: ValueFn, rf: ValueFn) -> PredFn:
    def pred(event: Any) -> bool:
        a = lf(event)
        b = rf(event)
        if a is MISSING or b is MISSING:
            return False  # MISSING fails every comparison
        if op == "==":
            return _safe_eq(a, b)
        if op == "!=":
            return not _safe_eq(a, b)
        ta, tb = type(a), type(b)
        num = (int, float)
        comparable = (
            (isinstance(a, num) and not isinstance(a, bool)
             and isinstance(b, num) and not isinstance(b, bool))
            or (ta is str and tb is str)
        )
        if not comparable:
            return False  # e.g. int vs str: fail instead of raising
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        if op == ">=":
            return a >= b
        raise AssertionError(f"unhandled operator {op}")  # pragma: no cover
    return pred


def _safe_eq(a: Any, b: Any) -> bool:
    # keep cross-type equality strict-ish: numbers compare with numbers,
    # everything else requires same type (bools are ints in Python, exclude)
    if isinstance(a, bool) != isinstance(b, bool):
        return False
    num = (int, float)
    a_num = isinstance(a, num) and not isinstance(a, bool)
    b_num = isinstance(b, num) and not isinstance(b, bool)
    if a_num != b_num:
        return False
    if a_num:
        return a == b
    if type(a) is not type(b):
        return False
    return a == b


def _make_in(lf: ValueFn, container_fn: ValueFn) -> PredFn:
    def pred(event: Any) -> bool:
        value = lf(event)
        if value is MISSING:
            return False
        container = container_fn(event)
        if isinstance(container, str):
            return isinstance(value, str) and value in container
        if isinstance(container, (list, tuple)):
            for item in container:
                if item is not MISSING and _safe_eq(value, item):
                    return True
            return False
        return False
    return pred


# ---------------------------------------------------------------------------
# Public API
# ---------------------------------------------------------------------------

_CACHE: Dict[str, PredFn] = {}


def exists_fn(path: Tuple[str, ...]) -> PredFn:
    return lambda event: lookup(event, path) is not MISSING


# Wire exists(path) into the parser grammar.
_original_comparison = _Parser.comparison


def _comparison_with_exists(self: "_Parser") -> PredFn:
    tok = self.peek()
    nxt = self.tokens[self.i + 1] if self.i + 1 < len(self.tokens) else None
    if tok.kind == "exists" and nxt is not None and nxt.kind == "op" \
            and nxt.value == "(":
        self.next()  # exists
        self.next()  # (
        ptok = self.next()
        if ptok.kind != "path":
            raise SyntaxError(
                f"exists() requires a dotted path at position {ptok.pos}")
        self.expect_op(")")
        return exists_fn(ptok.value)
    return _original_comparison(self)


_Parser.comparison = _comparison_with_exists  # type: ignore[method-assign]


def compile_filter(src: str) -> Callable[[Any], bool]:
    """Compile *src* into a predicate ``callable(event) -> bool``.

    Raises SyntaxError on malformed input. Never uses eval/exec; the
    source is parsed into pure Python closures.
    """
    if not isinstance(src, str):
        raise TypeError("filter source must be a string")
    cached = _CACHE.get(src)
    if cached is None:
        cached = _Parser(tokenize(src)).parse()
        _CACHE[src] = cached
    return cached


__all__ = ["compile_filter", "MISSING", "lookup"]

